t-problemas"]}',NULL,1,0,'{"id":"seed-les-mat-8","title":"¿Qué hora es?","objective":"Leer la hora en relojes analógicos y digitales.","program":"Medición y tiempo","courseId":"seed-course-matematicas","courseUnitId":"seed-unit-mat-4","duration":40,"materials":[],"reflection":"¿Qué aprendiste y cómo lo aplicarías?","activities":[{"id":"seed-les-mat-8-a1","position":0,"title":"Nuestra rutina","minutes":5,"phase":"start","purpose":"explore","grouping":"whole-class","instructions":"","blocks":[{"id":"seed-les-mat-8-a1-b1","kind":"text","richContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"¿A qué hora entramos, salimos al recreo y nos vamos? Escríbanlo en el pizarrón."}]}]}}]},{"id":"seed-les-mat-8-a2","position":1,"title":"Relojes de papel","minutes":20,"phase":"develop","purpose":"explain","grouping":"pairs","instructions":"","blocks":[{"id":"seed-les-mat-8-a2-b1","kind":"text","richContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Con su reloj de papel, marquen las horas de la rutina. Una persona dice la hora y la otra la marca."}]}]}},{"id":"seed-les-mat-8-a2-b2","kind":"resource","resourceId":"seed-res-mat-reloj"}]},{"id":"seed-les-mat-8-a3","position":2,"title":"Problema del recreo","minutes":15,"phase":"close","purpose":"assess","grouping":"individual","instructions":"","blocks":[{"id":"seed-les-mat-8-a3-b1","kind":"question","richContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El recreo empieza a las 10:15 y dura 30 minutos. ¿A qué hora termina?"}]}]},"options":["10:45","10:30","11:15"],"answer":0}]}],"publishedAt":"2026-09-11T16:00:00.000Z","shareCode":"D-4C25B96184DE5D24","sequence":"start-develop-close","outcomeIds":["seed-out-mat-medir","seed-out-mat-problemas"],"outcomes":[{"id":"seed-out-mat-medir","code":"RA4","statement":"Mide longitudes y lee la hora en relojes analógicos y digitales."},{"id":"seed-out-mat-problemas","code":"RA5","statement":"Elige y justifica la operación que resuelve un problema de su entorno."}],"resources":[{"id":"seed-res-mat-reloj","courseId":"seed-course-matematicas","title":"Guía docente: leer la hora","description":"Secuencia sugerida y errores frecuentes al leer relojes analógicos.","kind":"text","content":"1. Empieza por las horas en punto con la manecilla corta.\n2. Introduce las medias horas con la imagen del reloj partido a la mitad.\n3. Cuenta de 5 en 5 para los minutos.\n\nError frecuente: leer la manecilla larga como hora. Pide que la nombren en voz alta: «la corta dice la hora».","status":"published","version":1,"updatedAt":"2026-08-13T04:24:00.000Z","termIds":["seed-tag-guide"]}],"revision":1}',1,1,1,'2026-09-11T16:00:00.000Z','seed-unit-mat-4' WHERE EXISTS(SELECT 1 FROM organizations WHERE id='org-demo');
